    const surfaceRef = React.useRef(null);
    const scrollRef = React.useRef(null);
    const pageRef = React.useRef(null);
    // R164: the off-screen mirror used to find where the pages break, the
    // signature that keeps it from re-measuring an unchanged manuscript, and
    // the last page numbers we published (so a scroll can tell a page leaving
    // from a page coming back without re-measuring anything).
    const pageMirrorRef = React.useRef(null);
    const pageSigRef = React.useRef('');
    const pageStateRef = React.useRef({
      list: [],
      finished: 0,
      total: 0,
      fresh: -1,
      back: false,
      geo: null,
    });
    // R166: the pile itself (the flight animations need its cards' final
    // positions) and the sheet clone currently in the air.
    const pileRef = React.useRef(null);
    const flyingRef = React.useRef(null);
    // The sheet is asked for one settle animation per finished page; a page
    // coming back must not animate it, or the desk would twitch on every
    // upward scroll.
    const settleTimerRef = React.useRef(0);
    const pagesTimerRef = React.useRef(0);
    const titleRef = React.useRef(null);
    // R41 ①: the title last accepted by the app. Escape restores it, and it is
    // reset on every chapter switch so a stale string can never be restored
    // into a different chapter.
    const titleSavedRef = React.useRef('');
    const titleBusyRef = React.useRef(false);
    const stackRef = React.useRef(null);
    const hlRef = React.useRef(null);
    const caretRef = React.useRef(null);
    // The painted thick caret (positioned by paintCaret from measureCaret).
    const cursorRef = React.useRef(null);
    // R135: the lamp that follows the caret's line, and the dog-ear that marks
    // where the pen was left when a chapter is reopened. Both are painted from
    // the same measurement plan as the caret, so neither measures on its own.
    const lampRef = React.useRef(null);
    const foldRef = React.useRef(null);
    const lampDimRef = React.useRef(0);
    // R135: true while the dog-ear should stay folded. Set when a chapter is
    // reopened on a saved caret, cleared by the first keystroke or by the
    // six-second timer, whichever comes first.
    const foldPendingRef = React.useRef(false);
    const foldTimerRef = React.useRef(0);
    const lampTimerRef = React.useRef(0);
    // R46: the two veils that fade everything but the line being written.
    const veilTopRef = React.useRef(null);
    const veilBotRef = React.useRef(null);
    // Content-space top of the caret's line, written by every measure pass.
    // Scrolling does not change it, which is what lets a scroll event repaint
    // the fade without measuring anything. -1 means "not measured yet".
    const focusTopRef = React.useRef(-1);
    /**
     * R71: the caret's paragraph, in scroller content coordinates, cached by the
     * measure pass so paintFocus() can run from a scroll listener without
     * measuring anything (a Range per scroll event would force a reflow).
     */
    const paraBandRef = React.useRef(null);
    // Pending frame for that repaint (0 = none queued).
    const focusRafRef = React.useRef(0);
    const findInputRef = React.useRef(null);
    const replaceInputRef = React.useRef(null);

    const propsRef = React.useRef(p);
    propsRef.current = p;
    const cfgRef = React.useRef(null);
    cfgRef.current = { autoSaveMs, typewriterOn, fontSize, lineHeight, focusOn, focusFollows };

    const highlightsRef = React.useRef([]);
    // R47: persistent annotations, kept apart from `highlightsRef` on purpose —
    // the advice panel owns that one and clears it whenever the writer moves on,
    // and it must not be able to wipe the writer's own underlines.
    const marksRef = React.useRef([]);
    const saveTimerRef = React.useRef(0);
    // rAF handle for the coalesced measure pass (0 = none queued).
    const measureRafRef = React.useRef(0);
    // Safety timer paired with the rAF handle: a throttled frame (hidden tab)
    // still measures within MEASURE_MS, and whichever fires first cancels the
    // other, so one burst of input produces exactly one pass.
    const measureTimerRef = React.useRef(0);
    const measureQueuedRef = React.useRef(false);
    const noticeTimerRef = React.useRef(0);
    const manualAtRef = React.useRef(-1e9);
    // R68/R70: true while the last caret movement came from ArrowLeft /
    // ArrowRight. Unlike manualAtRef it does not freeze the viewport forever —
    // it parks the typewriter and the band together, so arrowing along a line
    // never slides the page, and typing puts both back.
