      const next = resolveScroller(true).el;
      if (surfaceRef.current) {
        const kind = scrollerKindRef.current;
        if (surfaceRef.current.getAttribute('data-scroller') !== kind) {
          surfaceRef.current.setAttribute('data-scroller', kind);
        }
      }
