                      includeMeta: draft.exportIncludeMeta !== false,
                      appendOn: draft.exportSignatureOn === true,
                      appendText: String(draft.exportSignature || ''),
                      options: { includeMeta: draft.exportIncludeMeta !== false, pageBreaks: true, toc: false },
